import React, { useState, useEffect } from 'react';
import './PostForm.css';

const PostForm = ({ onSubmit, onUpdate, editingPost, onCancelEdit, loading }) => {
  const [formData, setFormData] = useState({
    title: '',
    content: '',
    author: '',
    publishedDate: new Date().toISOString().split('T')[0]
  });
  const [errors, setErrors] = useState({});
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    if (editingPost) {
      setFormData({
        title: editingPost.title,
        content: editingPost.content,
        author: editingPost.author,
        publishedDate: new Date(editingPost.publishedDate).toISOString().split('T')[0]
      });
      setErrors({});
    } else {
      setFormData({
        title: '',
        content: '',
        author: '',
        publishedDate: new Date().toISOString().split('T')[0]
      });
      setErrors({});
    }
  }, [editingPost]);

  const validateForm = () => {
    const newErrors = {};
    if (!formData.title.trim()) newErrors.title = 'Title is required';
    if (!formData.content.trim()) newErrors.content = 'Content is required';
    if (!formData.author.trim()) newErrors.author = 'Author is required';
    if (!formData.publishedDate) newErrors.publishedDate = 'Published date is required';
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validateForm()) return;

    setSubmitting(true);
    try {
      if (editingPost) {
        await onUpdate(editingPost._id, formData);
      } else {
        await onSubmit(formData);
      }
      setFormData(prev => ({ ...prev, title: '', content: '', author: '' }));
    } catch (err) {
      setErrors({ submit: err.message });
    } finally {
      setSubmitting(false);
    }
  };

  const isEditing = Boolean(editingPost);

  return (
    <section className="post-form-section fade-in" aria-labelledby="form-title">
      <div className="post-form-card">
        <header className="form-header">
          <h2 id="form-title" className="form-title">
            {isEditing ? 'Edit Post' : 'Create New Post'}
          </h2>
          {isEditing && (
            <button type="button" className="btn btn-secondary btn-sm" onClick={onCancelEdit}>
              <svg width="16" height="16" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
              Cancel
            </button>
          )}
        </header>

        <form onSubmit={handleSubmit} className="post-form" noValidate>
          <div className="form-group">
            <label htmlFor="title" className="form-label">
              Title <span className="required" aria-hidden="true">*</span>
            </label>
            <input
              type="text"
              id="title"
              name="title"
              value={formData.title}
              onChange={handleChange}
              className={`form-input ${errors.title ? 'error' : ''}`}
              placeholder="Enter post title"
              maxLength={200}
              disabled={submitting || loading}
              aria-invalid={errors.title ? 'true' : 'false'}
              aria-describedby={errors.title ? 'title-error' : undefined}
            />
            {errors.title && (
              <span id="title-error" className="form-error" role="alert">{errors.title}</span>
            )}
          </div>

          <div className="form-group">
            <label htmlFor="author" className="form-label">
              Author <span className="required" aria-hidden="true">*</span>
            </label>
            <input
              type="text"
              id="author"
              name="author"
              value={formData.author}
              onChange={handleChange}
              className={`form-input ${errors.author ? 'error' : ''}`}
              placeholder="Enter author name"
              maxLength={100}
              disabled={submitting || loading}
              aria-invalid={errors.author ? 'true' : 'false'}
              aria-describedby={errors.author ? 'author-error' : undefined}
            />
            {errors.author && (
              <span id="author-error" className="form-error" role="alert">{errors.author}</span>
            )}
          </div>

          <div className="form-group">
            <label htmlFor="publishedDate" className="form-label">
              Published Date <span className="required" aria-hidden="true">*</span>
            </label>
            <input
              type="date"
              id="publishedDate"
              name="publishedDate"
              value={formData.publishedDate}
              onChange={handleChange}
              className={`form-input ${errors.publishedDate ? 'error' : ''}`}
              disabled={submitting || loading}
              aria-invalid={errors.publishedDate ? 'true' : 'false'}
              aria-describedby={errors.publishedDate ? 'date-error' : undefined}
            />
            {errors.publishedDate && (
              <span id="date-error" className="form-error" role="alert">{errors.publishedDate}</span>
            )}
          </div>

          <div className="form-group">
            <label htmlFor="content" className="form-label">
              Content <span className="required" aria-hidden="true">*</span>
            </label>
            <textarea
              id="content"
              name="content"
              value={formData.content}
              onChange={handleChange}
              className={`form-textarea ${errors.content ? 'error' : ''}`}
              placeholder="Write your blog post content here..."
              rows={8}
              disabled={submitting || loading}
              aria-invalid={errors.content ? 'true' : 'false'}
              aria-describedby={errors.content ? 'content-error' : undefined}
            />
            {errors.content && (
              <span id="content-error" className="form-error" role="alert">{errors.content}</span>
            )}
          </div>

          {errors.submit && (
            <div className="form-error form-error-submit" role="alert">
              <svg width="18" height="18" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
              </svg>
              {errors.submit}
            </div>
          )}

          <div className="form-actions">
            <button
              type="submit"
              className="btn btn-primary"
              disabled={submitting || loading}
            >
              {submitting && <span className="loading-spinner" aria-hidden="true"></span>}
              {isEditing ? 'Update Post' : 'Publish Post'}
            </button>
            {isEditing && (
              <button
                type="button"
                className="btn btn-outline"
                onClick={onCancelEdit}
                disabled={submitting || loading}
              >
                Cancel
              </button>
            )}
          </div>
        </form>
      </div>
    </section>
  );
};

export default PostForm;
